  ["0902a26299728a60"] = { "Dimmi, cosa alimenta questa vendetta?", "." },
  ["090393c40bccd5d1"] = { "Altre ossa da rosicchiare...", "." },
  ["0908aaec8e8621a9"] = { "Abbiamo rifornimenti in eccesso, ma non molti. Ce ne serviranno molti di più prima di poter lanciare un assalto di terra nel ⟦Field of Strife=Pian della Discordia⟧.", "." },
  ["0910a2ec828d7da2"] = { "Vediamo se i pesci abboccano.", "." },
  ["0910e10e1e55c9d0"] = { "Ah, il bel ⟦Menethil Harbor=Porto di Menethil⟧, con il miglior idromele da questa parte di ⟦Ironforge=Forgiardente⟧.", "." },
  ["0911fd4ef6215839"] = { "Sono qui per l'addestramento.", "." },
