  ["092fde2db170bc11"] = { "MUORI!", "." },
  ["0933991c8f46102b"] = { "<Benvenuto/Benvenuta> nel ⟦Cenarion Circle=Circolo Cenariano⟧, {class}.", "." },
  ["0939e36c484f268b"] = { "D'oh!", "." },
  ["093af810f377a1fb"] = { "Ciò che Sevine, Allistarj e Grol non avevano capito era che, proprio come i loro servitori erano vincolati alla terra, così lo sarebbero stati anche loro... Vedi, il prezzo della loro immortalità fu anche la prigionia e l'eterna servitù agli ordini di Razelikh. La crudele astuzia di Razelikh aveva trionfato ancora una volta.", "." },
  ["0945ea27c4f4cb21"] = { "Argh, mi serve aiuto qui!", "." },
  ["094bb50bd00238c1"] = { "Sono Samuel Hawke, il principale fornitore della Lega di Arathor qui al ⟦Arathi Basin=Bacino d'Arathi⟧. Man mano che migliorerai la tua reputazione presso di noi, ti metterò a disposizione una bella scelta di merci che potrebbero tornarti utili. Se ti servisse riparare qualcosa, offro anche quel servizio.", "." },
  ["095125d3d86e7a6d"] = { "Hakkar vivrà di nuovo!", "." },
  ["095ce64236f1cfdd"] = { "Il locandiere Norman, sull'anello superiore del ⟦Trade Quarter=Quartiere del Commercio⟧, è quello con cui parlare.", "." },
  ["095ecafa44dc21b5"] = { "Ah, «Evocazioni mistiche degli Arcimaghi di Dalaran». Perfetto.", "." },
  ["0963bd1ce1c233e7"] = { "Ha funzionato! Incredibile! A quanto pare non ho perso il tocco...", "." },
  ["09682a29a39541ea"] = { "Oh, ciao! Sono Hol'anyee, a capo della ricerca scientifica e biologica di Marshal Expeditions. Io e mio fratello, insieme ai nostri compagni, viaggiamo per Azeroth esplorandone la maestà selvaggia e indomita. È emozionante... ma, ehm... credo che stavolta di emozioni ce ne siamo procurate un po' troppe!", "." },
  ["096b147094e74ea5"] = { "Mi rallegra l'anima vedere le mura di ⟦Stormwind=Roccavento⟧ ergersi forti e alte.\n\nSe vuoi andare a Stratholme, temo di non poterti aiutare per il momento. Le torri vicino alla città in fiamme sono ancora contese, e per questo i miei poteri sono troppo deboli per aiutarti. Torna da me quando avrai vinto laggiù.", "." },
  ["096c14ce927969ca"] = { "Ho un pezzo di ferro nella schiena che mi ricorderà quella notte per il resto dei miei giorni.", "." },
  ["0973f174fb7f063d"] = { "Predoni da nord-ovest! Fuoco!", "." },
  ["097d23c31794e0c8"] = { "Ah, eccoci! Be', mettiamoci al lavoro, che ne dici...?", "." },
  ["0983cffc0e552b72"] = { "Il Soulflayer è sconfitto! Il nostro capo, Molthor, ora richiama altri suoi servitori...", "." },
  ["098a7819d2b55b0d"] = { "Come osi entrare nel mio santuario!", "." },
  ["098adb8f8d770eae"] = { "Bagnati nel mio potere! Abbeverati della mia forza! Combatti per la gloria dell'⟦Horde=Orda⟧!", "." },
  ["098d66d266c76f0d"] = { "Una dedizione di questa portata è rara. Hai dimostrato che la tua volontà è incrollabile, {name}. Sarai <ricompensato/ricompensata> generosamente per la tua salda vigilanza sul nostro mondo.\n\nDammi il tuo anello con sigillo, così che io possa rafforzarne l'incantamento.", "." },
  ["099573ea33ea20af"] = { "Posso insegnarti i segreti di ⟦Wolf Riding=Cavalca-Lupo⟧, se hai abbastanza oro per pagare la lezione!", "." },
  ["09a9fd5d45f9cf6a"] = { "Paval Reethe! Finalmente ti ho trovato. E adesso te la fai pure con gli ogre? Non temere, persino ai disertori e ai traditori si concede un po' di pietà.", "." },
  ["09ac3b2ccd14b9dc"] = { "Non è il momento, {name}.\n\nTi ha dato di volta il cervello?!", "." },
  ["09d50c398109bc27"] = { "Grazie per avermi salvato! La tua impresa non passerà inosservata.", "." },
  ["09dba50c81659f47"] = { "L'equilibrio è stato ristabilito!", "." },
  ["09e5cfbc3192caa8"] = { "Flagello nel ⟦Trade Quarter=Quartiere del Commercio⟧! Distruggere!", "." },
  ["09e7fec93769d8d7"] = { "La tua abilità dimostra un affetto duraturo per la nostra arte, ma vorrei un'ulteriore prova del tuo impegno. Ti affiderò un compito. Portalo a termine, e non chiederò altro.", "." },
  ["09ea0a89fc15f50f"] = { "Sbalorditivo. L'hai dominata, eppure lei conserva la consapevolezza di sé e le sue funzioni. Come hai fatto?", "." },
  ["09ead41bc6425f82"] = { "Il ⟦Iceblood Graveyard=Cimitero di Brinarossa⟧ è stato conquistato dall'⟦Alliance=Alleanza⟧!", "." },
  ["09ed4169939280af"] = { "⟦Arathi Basin=Bacino d'Arathi⟧ posto dove prendere da umani molli. Sir Malory Wheeler manda te là.", "." },
  ["09ef1a9e9bf63a70"] = { "Blu più rosso... prevedo...", "." },
  ["09f26a893906daf0"] = { "Dopo la ferocia che il mio popolo ha visto e subito, ti aspetti che io accetti un altro fardello, drago? Di certo sei pazzo.", "." },
  ["09f7252464bd51f9"] = { "Oh oh! I miei attrezzi sono finiti. Dovremo ricominciare da capo...", "." },
})
